CREATE TABLE ibexa_content_tree (node_id INT AUTO_INCREMENT NOT NULL, contentobject_id INT DEFAULT NULL, contentobject_is_published INT DEFAULT NULL, contentobject_version INT DEFAULT NULL, depth INT DEFAULT 0 NOT NULL, is_hidden INT DEFAULT 0 NOT NULL, is_invisible INT DEFAULT 0 NOT NULL, main_node_id INT DEFAULT NULL, modified_subnode INT DEFAULT 0, parent_node_id INT DEFAULT 0 NOT NULL, path_identification_string LONGTEXT DEFAULT NULL, path_string VARCHAR(255) DEFAULT '' NOT NULL, priority INT DEFAULT 0 NOT NULL, remote_id VARCHAR(100) DEFAULT '' NOT NULL, sort_field INT DEFAULT 1, sort_order INT DEFAULT 1, INDEX ibexa_content_tree_p_node_id (parent_node_id), INDEX ibexa_content_tree_path_ident (path_identification_string(50)), INDEX ibexa_content_tree_contentobject_id_path_string (path_string(191), contentobject_id), INDEX ibexa_content_tree_co_id (contentobject_id), INDEX ibexa_content_tree_depth (depth), INDEX ibexa_content_tree_path (path_string(191)), INDEX ibexa_content_modified_subnode (modified_subnode), INDEX ibexa_content_tree_remote_id (remote_id), PRIMARY KEY(node_id)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
